# WARNING: These PowerShell scripts were generated by Grok AI and have not been tested.
# They are provided as a starting point for Windows users. After testing on Windows,
# this warning comment can be removed.
#
# Generate (or refresh) CRLs for Root and Intermediate CAs
#
# Usage:
#   .\scripts\gencrl.ps1                  # generate all
#   .\scripts\gencrl.ps1 root             # only root
#   .\scripts\gencrl.ps1 intermediate-sig # only one intermediate
#

[CmdletBinding()]
param(
    [Parameter(Position = 0)]
    [string]$Target = "all"
)

$ErrorActionPreference = "Stop"

$ScriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path
$PKI_ROOT  = Resolve-Path (Join-Path $ScriptDir "..")
Set-Location $PKI_ROOT

if ($env:OPENSSL) {
    $OPENSSL = $env:OPENSSL
} else {
    $OPENSSL = "openssl"
}

function GenCrl-One {
    param(
        [string]$Name,
        [string]$OutName = $Name
    )

    Write-Host ">>> Generating CRL for $Name"
    Push-Location $Name
    try {
        & $OPENSSL ca -config openssl.cnf -gencrl -out "crl\$OutName.crl.pem"
    } finally {
        Pop-Location
    }
    Write-Host "    Wrote $Name\crl\$OutName.crl.pem"
    & $OPENSSL crl -in "$Name\crl\$OutName.crl.pem" -noout -text | Select-Object -First 12
    Write-Host ""
}

switch ($Target.ToLower()) {
    { $_ -in @("all") } {
        GenCrl-One "root-ca" "root-ca"
        GenCrl-One "intermediate-sig" "intermediate-sig"
        GenCrl-One "intermediate-tls" "intermediate-tls"
        GenCrl-One "intermediate-enc" "intermediate-enc"
    }
    { $_ -in @("root", "root-ca") } {
        GenCrl-One "root-ca" "root-ca"
    }
    { $_ -in @("intermediate-sig", "sig") } {
        GenCrl-One "intermediate-sig" "intermediate-sig"
    }
    { $_ -in @("intermediate-tls", "tls") } {
        GenCrl-One "intermediate-tls" "intermediate-tls"
    }
    { $_ -in @("intermediate-enc", "enc") } {
        GenCrl-One "intermediate-enc" "intermediate-enc"
    }
    default {
        Write-Host "Usage: .\scripts\gencrl.ps1 [all|root|intermediate-sig|intermediate-tls|intermediate-enc]"
        exit 1
    }
}

Write-Host "=== CRL generation complete ==="
